  "content": "import os
from abc import ABC, abstractmethod
from typing import Any, Dict, Optional

class BaseModel(ABC):
    """Abstract base class for all Nimbus LLM models."""

    def __init__(self, api_key: Optional[str] = None, **kwargs):
        self.api_key = api_key or os.getenv("NIMBUS_API_KEY")
        if not self.api_key:
            raise ValueError("NIMBUS_API_KEY not found. Please provide it or set the NIMBUS_API_KEY environment variable.")

    @abstractmethod
    def generate(self, prompt: str, **kwargs) -> Dict[str, Any]:
        """Generates a response from the model based on the given prompt."""
        pass

    @abstractmethod
    async def agenerate(self, prompt: str, **kwargs) -> Dict[str, Any]:
        """Asynchronously generates a response from the model based on the given prompt."""
        pass

    def _get_headers(self) -> Dict[str, str]:
        """Returns the authorization headers for API requests."""
        return {"Authorization": f"Bearer {self.api_key}"}

    def _get_base_url(self) -> str:
        """Returns the base URL for the API."""
        return os.getenv("NIMBUS_BASE_URL", "https://api.nimbus.ai/v1")
"
}

